parameters.jsCode:
// Validate and shape the enquiry for a WhatsApp template message.
//
// Meta rejects template variables that are empty, or that contain a newline
// or tab, or that have leading/trailing spaces. The visitor's message is
// free text, so every value has to be flattened before it is sent.

const RECIPIENT = $env.VJP_WHATSAPP_TO || '919032644115';

const clean = (value) => {
  const flat = String(value ?? '')
    .replace(/[\r\n\t]+/g, ' · ')   // newlines are not allowed in variables
    .replace(/\s{2,}/g, ' ')
    .trim();
  return flat === '' ? '-' : flat.slice(0, 900);
};

const body = $input.first().json.body ?? $input.first().json;

// Server-side honeypot check, in case a bot posts to the webhook directly
// rather than going through the page.
if (clean(body.website) !== '-') {
  return [{ json: { rejected: true, reason: 'honeypot' } }];
}

const name = clean(body.name);
const phone = clean(body.phone);

if (name === '-' || phone === '-') {
  return [{ json: { rejected: true, reason: 'missing name or phone' } }];
}

return [{
  json: {
    rejected: false,
    to: RECIPIENT,
    variables: [
      name,
      phone,
      clean(body.place),
      clean(body.subject),
      clean(body.message),
    ],
    received_at: new Date().toISOString(),
    raw: body,
  },
}];

