={{ JSON.stringify({
  messaging_product: 'whatsapp',
  to: $json.to,
  type: 'template',
  template: {
    name: 'vedajyothi_enquiry',
    language: { code: 'en' },
    components: [
      {
        type: 'body',
        parameters: $json.variables.map(v => ({ type: 'text', text: v })),
      },
    ],
  },
}) }}
